import {
	GetOrganizationsQuery,
	useGetOrganizationsQuery,
	type GetOrganizationsQueryResult
} from '@/generated/graphql'
import { ApolloQueryResult } from '@apollo/client'
import { useAuthStore } from '@/stores/authStore'

export type Organizations = NonNullable<
	GetOrganizationsQueryResult['data']
>['organizations']

interface UseGetOrganizationsState {
	organizations: Organizations | null
	loading: boolean
	previousData: Organizations | null
	refetch: () => Promise<ApolloQueryResult<GetOrganizationsQuery>>
}

export const useGetOrganizations = (): UseGetOrganizationsState => {
	const { auth } = useAuthStore()
	const { loading, data, refetch, previousData } = useGetOrganizationsQuery({
		skip: !auth
	})

	return {
		organizations: data?.organizations ?? null,
		previousData: previousData?.organizations ?? null,
		loading,
		refetch: async () => {
			return await refetch()
		}
	}
}
